    "html": "<section id=\"cierre\" style=\"background:#211714;color:#FAF6EE;font-family:Figtree, Arial, sans-serif;padding:96px 128px 150px;display:flex;flex-direction:column;gap:22px\"><div style=\"position:absolute;left:128px;top:300px;width:1300px;display:flex;flex-direction:column;gap:30px\">\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:600;font-size:22px;line-height:1.2;letter-spacing:3px;text-transform:uppercase;color:#FCDC8D\">Viernes 13 · 13:00–18:00</p><h1 style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:140px;line-height:.95;letter-spacing:-4px\">¡A rodar!</h1>\n<p style=\"font-size:28px;line-height:1.45;color:#CFC6BE;max-width:1000px\">Doce vídeos, cuatro bloques de personas y una casa. Si algo cambia en el set, se actualiza aquí.</p></div><img src=\"/pitch/barkita/logo-h-hueso.png\" alt=\"Barkita\" style=\"position:absolute;left:128px;bottom:66px;width:150px;height:24px;object-fit:contain\"><p style=\"position:absolute;left:300px;bottom:62px;width:1100px;font-size:24px;line-height:1.2;color:#CFC6BE\"></p><p style=\"position:absolute;right:128px;bottom:62px;width:120px;text-align:right;font-family:Inter, Arial, sans-serif;font-weight:700;font-size:24px;line-height:1.2\">11</p></section>"
